  ('ru', 'site.doctor.integration.error.inUse', $json$"У этой интеграции теперь есть история или связанные настройки (коннекторы, агенты, токены приёма, импорты или правила оповещений), её нельзя удалить. Архивируйте её."$json$::jsonb),
