  ('ar', 'site.doctor.integration.error.inUse', $json$"أصبح لهذا التكامل سجل أو إعدادات مرتبطة (موصلات أو وكلاء أو رموز استيعاب أو عمليات استيراد أو قواعد تنبيه) ولا يمكن حذفه. قم بأرشفته بدلًا من ذلك."$json$::jsonb),
