  ('hi', 'site.doctor.integration.error.inUse', $json$"इस इंटीग्रेशन का अब इतिहास है या इससे जुड़ी सेटिंग्स हैं (कनेक्टर, एजेंट, इनजेशन टोकन, इंपोर्ट या अलर्ट नियम), इसलिए इसे हटाया नहीं जा सकता। इसे संग्रहित करें।"$json$::jsonb),
